import java.util.Scanner;

public class Wordle {
    public static Scanner input;
    public static String[] guesses;
    public static int numberOfGuesses;
    public static int maxWordLength;
    private static String answer;
    // These constants colour the output.
    private static final String ANSI_RESET = "\u001B[0m";
    private static final String ANSI_GREEN = "\u001B[32m";
    private static final String ANSI_YELLOW = "\u001B[33m";

    public static void main(String[] args) {
        gameIntro();
        gameSetup();
        displayGuesses();
        runGame();
    }

    public static void gameIntro() {
        input = new Scanner(System.in);
        System.out.println("******************************************");
        System.out.println("   WELCOME TO WORDLE, a very fun game!");
        System.out.println("******************************************");
        System.out.println("This game is for 2 people.");
        System.out.print("Player 1, please type a 5-letter word: ");
        answer = input.next();
        clearConsole();
        System.out.println("Now, player 2 can start guessing:");
    }

    public static void gameSetup() {
        numberOfGuesses = 6;
        guesses = new String[numberOfGuesses];
        maxWordLength = 5;
        initializeGuesses();
    }

    public static void initializeGuesses() {
        for (int index = 0; index < numberOfGuesses; index++) {
            guesses[index] = "-----";
        }
    }

    public static void displayGuesses() {
        for (int index = 0; index < numberOfGuesses; index++) {
            System.out.println(guesses[index]);
        }
    }

    public static void clearConsole() {
        System.out.print("\u001B[H\u001B[2J");
    }

    public static void runGame() {
        for (int guessNumber = 0; guessNumber < numberOfGuesses; guessNumber++) {
            String userGuess = input.next();
            clearConsole();
            StringBuilder coloredGuess = new StringBuilder(maxWordLength);
            for (int index = 0; index < userGuess.length(); index++) {
                char userGuessChar = userGuess.charAt(index);
                if (userGuessChar == answer.charAt(index)) {
                    coloredGuess.append(ANSI_GREEN + userGuessChar + ANSI_RESET);
                } else {
                    int position = answer.indexOf(userGuessChar);
                    if (position >= 0) {
                        coloredGuess.append(ANSI_YELLOW + userGuessChar + ANSI_RESET);
                    } else {
                        coloredGuess.append(userGuessChar);
                    }
                }
            } // inner loop
            guesses[guessNumber] = coloredGuess.toString();
            displayGuesses();
            if (userGuess.equals(answer)) {
                System.out.println("Congratulations! You have guessed the word correctly!");
                return;
            }
            if (guessNumber == numberOfGuesses - 1) {
                System.out.println("You have run out of guesses! The word was " + answer + ".");
                return;
            }
        }
    }
}

